        pivot = augmented_matrix[i][i]
        if pivot == 0:
            continue

        for j in range(i, n+1):
            augmented_matrix[i][j] /= pivot

        for j in range(n):
            if j != i:
                factor = augmented_matrix[j][i]
                for k in range(i, n+1):
                    augmented_matrix[j][k] -= factor * augmented_matrix[i][k]

    rank = 0
    for row in augmented_matrix:
        if any(row):
            rank += 1

    return rank

